style.css:
@-moz-document url-prefix("http://"), url-prefix("https://") {
/* 一般文字 */
  body, p, span, div, li, td, th {
    color: #111111 !important;   /* 深灰，接近黑色 */
    font-weight: 500 !important; /* 比正常字稍粗 (400 → 500) */
  }

  /* 標題 & 粗體 */
  h1, h2, h3, h4, h5, h6, strong, b {
    color: #000000 !important;   /* 純黑 */
    font-weight: 700 !important; /* 粗體 */
  }

  /* 連結 */
  a {
    color: #222222 !important;   /* 比預設深 */
    font-weight: 500 !important;
  }
}
